28	// Delta-based ("push") PageRank. Instead of recomputing every rank from
29	// scratch each round, only the *change* in rank (Delta) is propagated, and only
30	// vertices whose Delta is still significant relative to their accumulated rank
31	// stay on the frontier. This makes later rounds cheap once most of the graph
32	// has converged.
33	
34	//pushes the change in rank of each active vertex to its out-neighbors
35	template <class vertex>
36	struct PR_F {
37	  double* Delta, *nghSum;
38	  vertex* V;
39	  PR_F(double* _Delta, double* _nghSum, vertex* _V) :
40	    Delta(_Delta), nghSum(_nghSum), V(_V) {}
41	  inline bool update(uintE s, uintE d) {
42	    double oldVal = nghSum[d];
43	    nghSum[d] += Delta[s]/V[s].getOutDegree();
44	    return oldVal == 0.0; //true only for the first contribution into d
45	  }
46	  inline bool updateAtomic (uintE s, uintE d) { //atomic version of Update
47	    volatile double oldV, newV;
48	    do { //fetch-and-add on a double
49	      oldV = nghSum[d]; newV = oldV + Delta[s]/V[s].getOutDegree();
50	    } while(!CAS(&nghSum[d],oldV,newV));
51	    return oldV == 0.0;
52	  }
53	  inline bool cond (uintE d) { return cond_true(d); }
54	};
55	
56	//vertex map to compute the initial Delta of each vertex (first round only)
57	struct PR_Vertex_F_FirstRound {
58	  double damping, addedConstant, one_over_n, epsilon2;
59	  double* p, *Delta, *nghSum;
60	  PR_Vertex_F_FirstRound(double* _p, double* _Delta, double* _nghSum,
61	                         double _damping, double _one_over_n, double _epsilon2) :
62	    p(_p), Delta(_Delta), nghSum(_nghSum), damping(_damping),
63	    one_over_n(_one_over_n), addedConstant((1-_damping)*_one_over_n),
64	    epsilon2(_epsilon2) {}
65	  inline bool operator () (uintE i) {
66	    Delta[i] = damping*nghSum[i]+addedConstant;
67	    p[i] += Delta[i];
68	    Delta[i] -= one_over_n; //subtract off the delta from initialization
69	    return (fabs(Delta[i]) > epsilon2*p[i]); //stay active if change is large
70	  }
71	};
72	
73	//vertex map to update Delta and p (rounds after the first)
74	struct PR_Vertex_F {
75	  double damping, epsilon2;
76	  double* p, *Delta, *nghSum;
77	  PR_Vertex_F(double* _p, double* _Delta, double* _nghSum,
78	              double _damping, double _epsilon2) :
79	    p(_p), Delta(_Delta), nghSum(_nghSum), damping(_damping),
80	    epsilon2(_epsilon2) {}
81	  inline bool operator () (uintE i) {
82	    Delta[i] = nghSum[i]*damping;
83	    if (fabs(Delta[i]) > epsilon2*p[i]) { p[i] += Delta[i]; return 1; }
84	    else return 0; //change too small to be worth propagating
85	  }
86	};
87	
88	//resets nghSum
89	struct PR_Vertex_Reset {
90	  double* nghSum;
91	  PR_Vertex_Reset(double* _nghSum) :
92	    nghSum(_nghSum) {}
93	  inline bool operator () (uintE i) {
94	    nghSum[i] = 0.0;
95	    return 1;
96	  }
97	};
