99	template <class vertex>
100	void Compute(graph<vertex>& GA, commandLine P) {
101	  long maxIters = P.getOptionLongValue("-maxiters",100);
102	  const long n = GA.n;
103	  const double damping = 0.85, epsilon = 0.0000001, epsilon2 = 0.01;
104	
105	  double one_over_n = 1/(double)n;
106	  double* p = newA(double,n);
107	  double* Delta = newA(double,n);
108	  double* nghSum = newA(double,n);
109	  bool* frontier = newA(bool,n);
110	  {parallel_for(long i=0;i<n;i++) {
111	    p[i] = 0.0;
112	    Delta[i] = one_over_n; //initial delta propagation from each vertex
113	    nghSum[i] = 0.0;
114	    frontier[i] = 1;
115	  }}
116	
117	  vertexSubset Frontier(n,n,frontier);
118	  bool* all = newA(bool,n);
119	  {parallel_for(long i=0;i<n;i++) all[i] = 1;}
120	  vertexSubset All(n,n,all); //all vertices, used as the vertexFilter input
121	
122	  long iters = 0;
123	  while(iters < maxIters) {
124	    iters++;
125	    // (a) push Delta along the out-edges of the active vertices. The output
126	    // frontier is computed by the vertexFilter below, so no_output is used.
127	    edgeMap(GA,Frontier,PR_F<vertex>(Delta,nghSum,GA.V),GA.m/20, no_output | dense_forward);
128	    // (b) turn the accumulated neighbor sums into new Deltas, fold them into p,
129	    // and keep only the vertices whose Delta is still significant
130	    vertexSubset active = (iters == 1) ?
131	      vertexFilter(All,PR_Vertex_F_FirstRound(p,Delta,nghSum,damping,one_over_n,epsilon2)) :
132	      vertexFilter(All,PR_Vertex_F(p,Delta,nghSum,damping,epsilon2));
133	    //compute L1-norm of Delta (nghSum is reused as scratch space, then reset)
134	    {parallel_for(long i=0;i<n;i++) nghSum[i] = fabs(Delta[i]);}
135	    double L1_norm = sequence::plusReduce(nghSum,n);
136	    if(L1_norm < epsilon) { active.del(); break; }
137	    //reset nghSum for the next round
138	    vertexMap(All,PR_Vertex_Reset(nghSum));
139	    Frontier.del();
140	    Frontier = active; //set new frontier
141	  }
142	
143	  double sum = sequence::plusReduce(p,n);
144	  cout << setprecision(10) << "PageRankDelta sum: " << sum << endl;
145	  cout << "PageRankDelta iters: " << iters << endl;
146	
147	  Frontier.del(); All.del();
148	  free(p); free(Delta); free(nghSum);
149	}
