47	  double damping;
48	  double addedConstant;
49	  double* p_curr;
50	  double* p_next;
51	  PR_Vertex_F(double* _p_curr, double* _p_next, double _damping, long n) :
52	    p_curr(_p_curr), p_next(_p_next),
53	    damping(_damping), addedConstant((1-_damping)*(1/(double)n)){}
54	  inline bool operator () (uintE i) {
55	    p_next[i] = damping*p_next[i] + addedConstant;
56	    return 1;
57	  }
58	};
