72	void Compute(graph<vertex>& GA, commandLine P) {
73	  long maxIters = P.getOptionLongValue("-maxiters",100);
74	  const long n = GA.n;
75	  const double damping = 0.85, epsilon = 0.0000001;
76	
77	  double one_over_n = 1/(double)n;
78	  double* p_curr = newA(double,n);
79	  {parallel_for(long i=0;i<n;i++) p_curr[i] = one_over_n;}
80	  double* p_next = newA(double,n);
81	  {parallel_for(long i=0;i<n;i++) p_next[i] = 0;} //0 if unchanged
82	  bool* frontier = newA(bool,n);
83	  {parallel_for(long i=0;i<n;i++) frontier[i] = 1;}
84	
85	  vertexSubset Frontier(n,n,frontier);
86	
87	  // Points at the array holding the current PageRank values once the loop ends.
88	  double* p_final = p_curr;
89	
90	  long iter = 0;
91	  while(iter++ < maxIters) {
92	    // (a) spread the rank of every vertex along its out-edges
93	    edgeMap(GA,Frontier,PR_F<vertex>(p_curr,p_next,GA.V),0, no_output);
94	    // (b) apply the damping factor
95	    vertexMap(Frontier,PR_Vertex_F(p_curr,p_next,damping,n));
96	    //compute L1-norm between p_curr and p_next
97	    {parallel_for(long i=0;i<n;i++) {
98	      p_curr[i] = fabs(p_curr[i]-p_next[i]);
99	      }}
100	    double L1_norm = sequence::plusReduce(p_curr,n);
101	    if(L1_norm < epsilon) { p_final = p_next; break; }
102	    //reset p_curr
103	    vertexMap(Frontier,PR_Vertex_Reset(p_curr));
104	    swap(p_curr,p_next);
105	    p_final = p_curr;
106	  }
107	
108	  double sum = sequence::plusReduce(p_final,n);
109	  cout << setprecision(10) << "PageRank sum: " << sum << endl;
110	
111	  Frontier.del(); free(p_curr); free(p_next);
112	}
